        type="button"
        data-testid="claim-defer"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          setRefused(undefined);
          defer.mutate(deferUntil);
        }}
      >
        Defer
      </button>{' '}
      Proofs <span data-testid="claim-proofs">{claim.proofs ?? 0}</span>{' '}
      <button
        type="button"
        data-testid="claim-proof"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          setRefused(undefined);
          proof.mutate();
        }}
      >
        Add proof
      </button>{' '}
      Split from <span data-testid="claim-split-from">{claim.splitFrom ?? ''}</span>{' '}
      <input
        data-testid="claim-split-amount"
        placeholder="Split amount"
        value={splitAmount}
        onChange={(e) => {
          setSplitAmount(e.target.value);
          split.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-split"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          setRefused(undefined);
          split.mutate(splitAmount);
        }}
      >
        Split
      </button>{' '}
      <input
        type="date"
        data-testid="claim-date-new"
        value={newDate}
        onChange={(e) => {
          setNewDate(e.target.value);
          redate.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-redate"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          split.reset();
          lock.reset();
          remind.reset();
          setRefused(undefined);
          redate.mutate(newDate);
        }}
      >
        Re-date
      </button>{' '}
      Reminded <span data-testid="claim-reminded">{claim.reminded ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="claim-remind"
        disabled={busy}
        onClick={() => {
          resetAll();
          remind.mutate();
        }}
      >
        Remind
      </button>{' '}
      <button
        type="button"
        data-testid="claim-edit"
        disabled={busy}
        onClick={() => {
          resetAll();
          const why = refusal();
          if (why === undefined) lock.mutate();
          else {
            setRefused(why);
            if (viewer()) openEditor();
          }
        }}
      >
        Edit
      </button>
      {editingId === claim.id && (
        <button
          type="button"
          data-testid="claim-cancel"
          onClick={() => {
            resetAll();
            unlock(claim.id);
            setEditing(undefined);
          }}
        >
          Cancel
        </button>
      )}{' '}
      {error && (
        <span data-testid="claim-error" role="alert">
          {error.message}
        </span>
      )}
    </>
  );
}

export const contribution = ClaimCells.fill({ order: 20, Component: ClaimStatusCell });
