package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * A claim's fields: an amount (required; a number with up to two decimals, 0.00 or more, or below 0.00
 * for a correction), a date (blank for the sheet's today), a note (may be empty) and the number of the
 * claim a correction corrects (blank for none). Publishes them parsed, with the user making the change.
 */
public class ValidateClaim {

    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim,
            Out<ChangedBy> changedBy) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        claim.set(parse(request));
        changedBy.set(by);
    }

    /** The claim form's fields parsed under its rules; shared with every form that enters a claim's fields. */
    static ClaimInput parse(ClaimRequest request) throws BadRequestException {
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
        BigDecimal amount = ClaimAmount.signed(request == null ? null : request.amount());
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("Enter a date as YYYY-MM-DD");
            }
        }
        if (note.length() > 1000) {
            throw new BadRequestException("A note is at most 1000 characters");
        }
        String correctsNumber = null;
        if (!corrects.isEmpty()) {
            if (!corrects.matches("\\d{1,9}|.{1,200}-\\d{1,9}")) {
                throw new BadRequestException("Name the corrected claim by its number");
            }
            correctsNumber = corrects.matches("\\d+") ? String.valueOf(Integer.parseInt(corrects)) : corrects;
        }
        return new ClaimInput(amount, parsed, note, correctsNumber);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim, ClaimRepository repository, SheetRepository sheets) {
        claim.setAmount(input.amount());
        claim.setDate(input.date() != null ? input.date() : sheets.today(claim.getSheetId()));
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
        repository.update(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Refuses an edited correction that does not name a SETTLED claim of its person, or a claim naming one that is not a correction. */
public class RefuseBadEditedCorrection {
    public void check(@Val Claim claim, @Val ClaimInput input, ClaimRepository repository) throws BadRequestException {
        RefuseBadCorrection.refuse(input, claim.getSheetId(), claim.getPersonId(), repository);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** Drops the user's lock on the claim: its editor was saved or cancelled. */
public class ReleaseClaimLock {
    public void release(@Val Claim claim, @Val ChangedBy by, ClaimLockRepository locks) {
        locks.release(claim.getId(), by.name());
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's fields as typed: amount, date (blank for the sheet's today), note and the number of the
 * claim a correction corrects (blank for none), and the signed-in user (`by`) making the change.
 */
public record ClaimRequest(String amount, String date, String note, String corrects, String by) {
}

